\begin{lemma}[The adapted chart at a regular point]
\label{lem:adapted-chart-scalar-affine}

\uses{lem:straighten-scalar-affine}




Let $M$ be a smooth manifold without boundary, $f \in C^\infty(M)$, and $y \in M$ with $df_y \neq 0$. Let $\kappa$ be a chart of $M$ at $y$. Then there is a diffeomorphism $G$ between open subsets of the model space, with $\kappa(y) \in \operatorname{dom} G \subseteq \operatorname{im} \kappa$ and $G(\kappa(y)) = \kappa(y)$, such that
\[
  f\bigl(\kappa^{-1}(G^{-1}(v))\bigr) = f(y) + df_y(v - \kappa(y))
\]
for every $v$ in the image of $G$. Thus in the corrected chart $G \circ \kappa$ the function $f$ is affine, and the level set $f^{-1}(f(y))$ is the affine hyperplane slice $\{v : df_y(v - \kappa(y)) = 0\}$.
\end{lemma}

\begin{proof}

\uses{lem:straighten-scalar-affine}
The coordinate representative $f \circ \kappa^{-1}$ is smooth on the open set $\operatorname{im} \kappa$, and because $M$ has no boundary its derivative at $\kappa(y)$ is exactly $df_y$. Apply Lemma \ref{lem:straighten-scalar-affine} with $s = \operatorname{im}\kappa$, $u_0 = \kappa(y)$ and $\ell = df_y \neq 0$, and rewrite $f(\kappa^{-1}(G^{-1}(v)))$ using $\kappa^{-1} \circ \kappa = \operatorname{id}$ on the chart domain.
\end{proof}

